def json_pointer(doc, pointer: str):
    if not isinstance(pointer, str) or (pointer and not pointer.startswith("/")):
        raise ValueError("JSON Pointer must be empty or start with '/'")

    if pointer == "":
        return doc

    def decode_segment(segment):
        result = []
        i = 0
        while i < len(segment):
            if segment[i] == "~":
                if i + 1 >= len(segment) or segment[i + 1] not in "01":
                    raise ValueError("Invalid escape sequence in JSON Pointer")
                result.append("/" if segment[i + 1] == "1" else "~")
                i += 2
            else:
                result.append(segment[i])
                i += 1
        return "".join(result)

    current = doc

    for raw_segment in pointer[1:].split("/"):
        segment = decode_segment(raw_segment)

        if isinstance(current, dict):
            if segment not in current:
                raise ValueError("Missing object key")
            current = current[segment]
        elif isinstance(current, list):
            if not segment or any(ch < "0" or ch > "9" for ch in segment):
                raise ValueError("Invalid array index")
            index = int(segment)
            if index >= len(current):
                raise ValueError("Array index out of range")
            current = current[index]
        else:
            raise ValueError("Cannot index into this value")

    return current
